// Code node "Plan page fetches" (Workflow A). Mode: Run Once for All Items.
//
// Input: the robots.txt response for the current source (HTTP node, full response).
// Output: one item per page to fetch, or a single { robots_blocked: true } item.
//
// robots.txt is honoured in both modes. In fixtures mode the saved robots.txt is checked
// against the real page URLs, so a fixture run makes the same decision a live run would.
// Matching follows RFC 9309: the group for our product token wins over "*", the longest
// matching rule wins, Allow wins a tie, and "*" / "$" wildcards are supported. A 4xx
// robots.txt means no restrictions. A 5xx or unreachable robots.txt means "assume
// disallowed", as the RFC requires.

function parseRobots(text) {
  const groups = [];
  let current = null;
  let lastWasAgent = false;
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.replace(/#.*$/, '').trim();
    const match = line.match(/^([A-Za-z-]+)\s*:\s*(.*)$/);
    if (!match) continue;
    const field = match[1].toLowerCase();
    const value = match[2].trim();
    if (field === 'user-agent') {
      if (!lastWasAgent) {
        current = { agents: [], rules: [] };
        groups.push(current);
      }
      current.agents.push(value.toLowerCase());
      lastWasAgent = true;
    } else if ((field === 'allow' || field === 'disallow') && current) {
      if (value !== '') current.rules.push({ allow: field === 'allow', path: value });
      lastWasAgent = false;
    } else {
      lastWasAgent = false;
    }
  }
  return groups;
}

function ruleMatches(rulePath, path) {
  const anchored = rulePath.endsWith('$');
  const body = anchored ? rulePath.slice(0, -1) : rulePath;
  const pattern = body
    .split('*')
    .map((part) => part.replace(/[.+?^${}()|[\]\\]/g, '\\$&'))
    .join('.*');
  return new RegExp(`^${pattern}${anchored ? '$' : ''}`).test(path);
}

// The Code-node sandbox has no URL global, so the path and query are taken with a regex.
function pathAndQuery(url) {
  const match = String(url).match(/^[a-z][a-z0-9+.-]*:\/\/[^/?#]*([^#]*)/i);
  const rest = match && match[1] ? match[1] : '/';
  const withSlash = rest.startsWith('/') ? rest : `/${rest}`;
  const queryAt = withSlash.indexOf('?');
  const path = queryAt === -1 ? withSlash : withSlash.slice(0, queryAt);
  const query = queryAt === -1 ? '' : withSlash.slice(queryAt);
  try {
    return decodeURIComponent(path) + query;
  } catch {
    return path + query;
  }
}

function isAllowed(groups, productToken, url) {
  const token = productToken.toLowerCase();
  const own = groups.filter((g) => g.agents.some((a) => a !== '*' && token.startsWith(a)));
  const chosen = own.length ? own : groups.filter((g) => g.agents.includes('*'));
  const rules = chosen.flatMap((g) => g.rules);
  const path = pathAndQuery(url);
  let best = null;
  for (const rule of rules) {
    if (!ruleMatches(rule.path, path)) continue;
    const longer = !best || rule.path.length > best.path.length;
    const tieAllow = best && rule.path.length === best.path.length && rule.allow;
    if (longer || tieAllow) best = rule;
  }
  return best ? best.allow : true;
}

function plan(source, config, robotsResponse) {
  const userAgent = config.crawl_user_agent;
  const productToken = userAgent.split('/')[0];
  const status = robotsResponse.statusCode ?? 0;
  if (status === 0) {
    // Network failure, not a robots decision: log it as an error so it can be retried tomorrow.
    return [{
      robots_blocked: true,
      run_status: 'error',
      http_status: null,
      error: `robots.txt unreachable: ${robotsResponse.error?.message ?? 'request failed'}`,
    }];
  }
  let groups;
  // HTTP Request with full response + text format puts the body in `data`.
  if (status >= 200 && status < 300) groups = parseRobots(String(robotsResponse.data ?? ''));
  else if (status >= 400 && status < 500) groups = [];
  else groups = [{ agents: ['*'], rules: [{ allow: false, path: '/' }] }];

  const fixtures = config.crawl_mode === 'fixtures';
  const pages = source.page_urls.map((url, i) => ({
    source_id: source.source_id,
    slug: source.slug,
    url,
    fetch_url: fixtures ? `http://fixtures/${source.slug}/${source.fixture_files[i]}` : url,
    user_agent: userAgent,
  }));
  const blocked = pages.filter((page) => !isAllowed(groups, productToken, page.url));
  if (blocked.length) {
    return [{
      robots_blocked: true,
      run_status: 'robots_blocked',
      http_status: status,
      error: `robots.txt disallows ${blocked.map((p) => p.url).join(', ')}`,
    }];
  }
  return pages.map((page) => ({ robots_blocked: false, ...page }));
}

// ---- n8n entry point ----
const source = $('Loop over sources').first().json;
const config = $('Load app_config').first().json.config;
return plan(source, config, $input.first().json).map((json) => ({ json }));

// Code node "Collect pages" (Workflow A). Mode: Run Once for All Items.
//
// Joins the per-page HTTP responses back into one item for the source. Pages are paired with
// their plan by position, which the HTTP Request node preserves. A source is only extracted
// when every page came back 200: a partial source would make products look removed and
// deactivate them a week later.

function collect(source, plans, responses) {
  const pages = plans.map((planned, i) => ({
    url: planned.url,
    status: responses[i]?.statusCode ?? 0,
    // HTTP Request with full response + text format puts the body in `data`.
    body: typeof responses[i]?.data === 'string' ? responses[i].data : '',
    error: responses[i]?.error?.message ?? null,
  }));
  const failed = pages.find((page) => page.status !== 200);
  if (failed) {
    return {
      fetch_ok: false,
      run_status: 'error',
      http_status: failed.status || null,
      error: failed.status ? `HTTP ${failed.status} for ${failed.url}` : `${failed.url}: ${failed.error ?? 'request failed'}`,
    };
  }
  return {
    fetch_ok: true,
    source_id: source.source_id,
    slug: source.slug,
    display_name: source.display_name,
    kind: source.kind,
    http_status: 200,
    pages: pages.map(({ url, body }) => ({ url, body })),
  };
}

// ---- n8n entry point ----
const source = $('Loop over sources').first().json;
const plans = $('Plan page fetches').all().map((item) => item.json);
const responses = $input.all().map((item) => item.json);
return [{ json: collect(source, plans, responses) }];

// Code node "Clean page text" (Workflow A). Mode: Run Once for All Items.
//
// Turns each fetched page into compact, structure-preserving text before hashing and
// extraction. Why not n8n's HTML node: the source pages have no <main> element and use
// generated IDs, so CSS selectors would break on the next redeploy. Plain text extraction
// would also flatten the rate and eligibility tables the LLM most needs. This cleaner keeps
// table rows as "cell | cell" lines and headings as "##" lines, and drops chrome
// (scripts, nav, header, footer, forms) and duplicate lines.
//
// The hash is taken over this text, not the raw HTML, so cosmetic markup changes (tracking
// IDs, build hashes) don't trigger a new LLM extraction.
//
// Input items:  { source_id, slug, pages: [{ url, body }] }
// Output items: { ...input without page bodies, text, text_chars, raw_chars }

const DROP_BLOCKS = [
  'script', 'style', 'noscript', 'svg', 'head', 'nav', 'header', 'footer',
  'form', 'iframe', 'button', 'select', 'template',
];

const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '-', mdash: '-',
  rsquo: "'", lsquo: "'", rdquo: '"', ldquo: '"', hellip: '...', bull: '-', middot: '-',
  rupee: '₹', inr: '₹', times: 'x', percnt: '%',
};

function decodeEntities(text) {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, code) => {
    if (code[0] === '#') {
      const value = code[1].toLowerCase() === 'x' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
      return Number.isFinite(value) ? String.fromCodePoint(value) : match;
    }
    const named = NAMED_ENTITIES[code.toLowerCase()];
    return named === undefined ? match : named;
  });
}

function htmlToText(html) {
  let s = html.replace(/<!--[\s\S]*?-->/g, ' ');
  for (const tag of DROP_BLOCKS) {
    s = s.replace(new RegExp(`<${tag}\\b[\\s\\S]*?</${tag}>`, 'gi'), ' ');
  }
  // Each table row becomes one "cell | cell" line. Cells often wrap their text in <p> or <div>,
  // which would otherwise split a row across lines and detach a lender's name from its rate.
  s = s.replace(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi, (_, row) => {
    const cells = row
      .split(/<\/t[dh]>/i)
      .map((cell) => cell.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim())
      .filter(Boolean);
    return `\n${cells.join(' | ')}\n`;
  });
  s = s
    .replace(/<h[1-6]\b[^>]*>/gi, '\n## ')
    .replace(/<li\b[^>]*>/gi, '\n- ')
    .replace(/<(br|p|div|section|article|ul|ol|table|tr|dt|dd)\b[^>]*>/gi, '\n')
    .replace(/<\/(p|div|section|article|ul|ol|table|tr|li|dt|dd|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  // Some CMSs (HDFC's included) ship entity-escaped HTML as text. Decoding reveals that markup,
  // so strip tags a second time and decode again.
  s = decodeEntities(decodeEntities(s).replace(/<[^>]+>/g, ' '));

  const lines = s
    .split('\n')
    .map((raw) =>
      raw
        .replace(/[ \t ]+/g, ' ')
        .replace(/(\s*\|\s*)+$/, '')
        .replace(/^(\s*\|\s*)+/, '')
        .trim(),
    )
    .filter((line) => line.length >= 2 && !/^[-#|\s]+$/.test(line));

  // Menus go first: if they were deduplicated first, a menu entry such as "SBI Personal Loan"
  // would knock out the real heading or table row with the same text further down.
  const seen = new Set();
  const kept = [];
  for (const line of dropLinkFarms(lines)) {
    // Dedupe on the content, so "- Age: 21 to 60" and "Age: 21 to 60" count as one line.
    const key = line.replace(/^(- |## )/, '').toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    kept.push(line);
  }
  return kept.join('\n');
}

// Mega-menus survive outside <nav> as long runs of short bullets ("- Car Loan", "- PMAY").
// Eligibility bullets almost always carry a number, a percentage or a rupee amount, so a run
// of 4+ short bullets with none of those is navigation and is dropped.
const HAS_FIGURE = /[0-9%₹]/;
function dropLinkFarms(lines) {
  const out = [];
  let run = [];
  const flush = () => {
    if (run.length < 4) out.push(...run);
    run = [];
  };
  for (const line of lines) {
    const isMenuLike = line.startsWith('- ') && line.length <= 40 && !HAS_FIGURE.test(line);
    if (isMenuLike) {
      run.push(line);
    } else {
      flush();
      out.push(line);
    }
  }
  flush();
  return out;
}

function cleanSource(item) {
  const pages = item.pages || [];
  const sections = pages.map((page) => `=== PAGE: ${page.url} ===\n${htmlToText(page.body || '')}`);
  const text = sections.join('\n\n');
  const { pages: _dropped, ...rest } = item;
  return {
    ...rest,
    page_urls: pages.map((page) => page.url),
    text,
    text_chars: text.length,
    raw_chars: pages.reduce((sum, page) => sum + (page.body || '').length, 0),
  };
}

// ---- n8n entry point ----
return $input.all().map((item) => ({ json: cleanSource(item.json) }));

// Code node "Build extraction request" (Workflow A). Mode: Run Once for All Items.
//
// S1, crawl-time compile: the page text goes to the LLM once per changed page, together with a
// strict JSON schema. The model reports values as stated on the page (amounts with their
// period, rates as written), a confidence per field group, and every remaining criterion
// classified as compilable, fuzzy or unknown_field. Unit conversion and every threshold
// decision happen afterwards in validate_products.js, as code, so the LLM never does
// arithmetic the engine depends on.
//
// The request is provider-neutral. The LLM gateway sub-workflow turns it into a Gemini (or
// other provider) call.

const PROMPT_VERSION = 'extract-v3';
const FACTS = ['monthly_income', 'credit_score', 'employment_status', 'age'];
const EMPLOYMENT = ['Salaried', 'Self-Employed', 'Business'];

const SYSTEM = `You extract personal-loan products and their eligibility rules from the text of an Indian lender or loan-comparison web page. Your output feeds an eligibility engine that knows only four facts about each applicant:
- monthly_income: net monthly income in INR
- credit_score: CIBIL score, 300 to 900
- employment_status: exactly one of "Salaried", "Self-Employed", "Business"
- age: in years

Rules:
1. Return one product per distinct lender product that the page describes with at least an interest rate or an eligibility rule. Comparison pages list many lenders: every lender with its own row in a rate table or an eligibility table is a product, even if it has no other mention, and everything the page says about the same lender (rate table row, eligibility table row, lender card) is merged into that one product. Ignore navigation, links, other loan types (home, car, gold, business, education loans) and generic advice that is not tied to a lender.
2. lender is the lender's usual name, such as "HDFC Bank" or "Aditya Birla Capital". product_name is the product as the page names it, such as "HDFC Personal Loan".
3. Interest rates are percent per annum, copied as stated. "10.99% p.a. onwards" means min 10.99 and max null.
4. List every stated minimum income in income_thresholds: amount in rupees as a plain number, and the period as written. "Rs.25,000 per month" is 25000 monthly. "Rs 5 lakh per annum" is 500000 annual. 1 lakh = 100000 and 1 crore = 10000000. employment lists the groups the threshold applies to (empty means everyone). Put any other condition, such as holding a salary account with the bank or working for a particular employer, in condition.
5. employment_allowed lists only groups the page clearly allows for this product. "salaried" maps to "Salaried". "self-employed" with no qualifier maps to "Self-Employed". "business owner" or "self-employed non-professional" maps to "Business". If the page says self-employed applicants are not eligible, list only "Salaried". If a group is described more narrowly than these three values (for example "self-employed professionals such as doctors and CAs", or "employees of private limited companies"), do not list it here. Add it to other_criteria instead. Leave employment_allowed empty when the page does not say.
6. credit_score_kind is "minimum" when the page states a score an applicant needs, must have or must meet for this lender, such as "you need a minimum credit score of 720", "CIBIL score: 685 or higher", "750 or more" or "at least 700". A stated requirement wins: if the page states a required score and elsewhere calls a score good, ideal or preferred, report the lowest required score with kind "minimum", and put the preferred score in other_criteria as compilable. Use "preferred" only when the page states no required score and only calls a score good, ideal or preferred. Otherwise use "not_stated", with min_credit_score null.
7. other_criteria holds every other eligibility condition for this product, each classified:
   - "compilable": can be checked with the four facts and an exact threshold, such as "CIBIL 750 or above preferred" or "minimum income Rs 40,000 for self-employed".
   - "fuzzy": depends only on the four facts but needs judgment to apply, such as "self-employed professionals" against employment_status "Self-Employed".
   - "unknown_field": depends on information the engine does not have, such as employer category, work experience, city, residence stability, a relationship with the bank, loan amount or existing debt.
   depends_on lists the facts involved. It is empty for unknown_field.
8. confidence, per field group: 1 when stated explicitly for this product; about 0.5 when inferred, ambiguous, or when two places on the page give this lender different values (then use the value from the lender's own card or section, and still say 0.5); 0 when not stated.
9. evidence is one short quote, under 200 characters, that supports the product's rules.
Return only products the text supports.`;

const NULLABLE_NUMBER = { type: ['number', 'null'] };
const NULLABLE_INTEGER = { type: ['integer', 'null'] };
const CONFIDENCE = { type: 'number', minimum: 0, maximum: 1 };

const SCHEMA = {
  type: 'object',
  properties: {
    products: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          lender: { type: 'string' },
          product_name: { type: 'string' },
          interest_rate_min_pct: NULLABLE_NUMBER,
          interest_rate_max_pct: NULLABLE_NUMBER,
          min_age: NULLABLE_INTEGER,
          max_age: NULLABLE_INTEGER,
          min_credit_score: NULLABLE_INTEGER,
          credit_score_kind: { type: 'string', enum: ['minimum', 'preferred', 'not_stated'] },
          income_thresholds: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                amount: { type: 'number' },
                period: { type: 'string', enum: ['monthly', 'annual'] },
                employment: { type: 'array', items: { type: 'string', enum: EMPLOYMENT } },
                condition: { type: ['string', 'null'] },
              },
              required: ['amount', 'period', 'employment', 'condition'],
              additionalProperties: false,
            },
          },
          employment_allowed: { type: 'array', items: { type: 'string', enum: EMPLOYMENT } },
          other_criteria: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                text: { type: 'string' },
                class: { type: 'string', enum: ['compilable', 'fuzzy', 'unknown_field'] },
                depends_on: { type: 'array', items: { type: 'string', enum: FACTS } },
              },
              required: ['text', 'class', 'depends_on'],
              additionalProperties: false,
            },
          },
          confidence: {
            type: 'object',
            properties: {
              interest_rate: CONFIDENCE,
              age: CONFIDENCE,
              credit_score: CONFIDENCE,
              income: CONFIDENCE,
              employment: CONFIDENCE,
            },
            required: ['interest_rate', 'age', 'credit_score', 'income', 'employment'],
            additionalProperties: false,
          },
          evidence: { type: 'string' },
        },
        required: [
          'lender', 'product_name', 'interest_rate_min_pct', 'interest_rate_max_pct',
          'min_age', 'max_age', 'min_credit_score', 'credit_score_kind', 'income_thresholds',
          'employment_allowed', 'other_criteria', 'confidence', 'evidence',
        ],
        additionalProperties: false,
      },
    },
  },
  required: ['products'],
  additionalProperties: false,
};

function buildRequest(source, config) {
  return {
    purpose: 'extract_products',
    prompt_version: PROMPT_VERSION,
    model: config.llm_model_extract,
    temperature: 0,
    max_output_tokens: 32768,
    system: SYSTEM,
    prompt: `Source: ${source.display_name} (${source.kind})\n\n${source.text}`,
    schema: SCHEMA,
  };
}

// ---- n8n entry point ----
const config = $('Load app_config').first().json.config;
return [{ json: buildRequest($input.first().json, config) }];

// Code node "Validate products" (Workflow A). Mode: Run Once for All Items.
//
// Turns the LLM's page-level extraction into the hard-filter columns of loan_products (S1) and
// applies the confidence guard (S6). Everything that decides who is filtered out happens here,
// in code that can be tested, never in the model:
//   * Ranges: rates must be in (0, 60] % p.a., ages in 18-100, scores in 300-900. Swapped
//     min/max values are put back in order.
//   * Income: annual amounts become monthly (divide by 12). The lowest threshold for anyone
//     becomes the SQL filter, so nobody is wrongly excluded. Stricter employment-specific
//     thresholds become `compilable` rules. Thresholds that depend on something we don't know
//     (salary account, employer) become `unknown_field` caveats.
//   * Credit score: only a stated minimum filters. A "preferred" score becomes a `compilable`
//     ranking rule. On a lender's own page, code also reads the text: a sentence that states a
//     score as a requirement ("you need a minimum credit score of 720", "CIBIL Score: 685 or
//     higher") sets the minimum, even if the model called it preferred. The lowest stated
//     requirement wins. On an aggregator page the stated requirement is the source's general
//     one ("Credit Score | CIBIL score of 750 or more"); it applies to each listed product that
//     states criteria of its own but no score. A sentence about what lenders will "consider" is
//     not an eligibility bar and is skipped.
//   * Income tiers reserved for a relationship we can't verify (the bank's own employees, its
//     salary-account holders, existing customers) don't set the floor; they stay caveats. The
//     floor is the general public's tier.
//   * S6: a hard-filter field whose confidence is below extraction_confidence_min is not used
//     as a filter (stored as NULL). It becomes a `fuzzy` criterion instead, so that product's
//     pairs go to the LLM with the stated value rather than being decided by an untrusted
//     rule.
//   * criteria_hash covers the decision-relevant criteria only (no confidences, no evidence),
//     so it changes exactly when matching could change.

const crypto = require('crypto');

const EMPLOYMENT = ['Salaried', 'Self-Employed', 'Business'];
const FACTS = ['monthly_income', 'credit_score', 'employment_status', 'age'];
const CLASSES = ['compilable', 'fuzzy', 'unknown_field'];
const MAX_MONTHLY_INCOME = 10000000;
const SUSPICIOUS_MONTHLY = 500000;

function num(value) {
  const n = typeof value === 'string' ? Number(value.replace(/,/g, '')) : value;
  return typeof n === 'number' && Number.isFinite(n) ? n : null;
}

function text(value) {
  return typeof value === 'string' ? value.replace(/\s+/g, ' ').trim() : '';
}

function rupees(n) {
  return `₹${Math.round(n).toLocaleString('en-IN')}`;
}

function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map((k) => [k, canonical(value[k])]));
  }
  return value;
}

function sha256(value) {
  return crypto.createHash('sha256').update(JSON.stringify(canonical(value))).digest('hex');
}

function rates(raw, issues) {
  let min = num(raw.interest_rate_min_pct);
  let max = num(raw.interest_rate_max_pct);
  for (const [name, value] of [['min', min], ['max', max]]) {
    if (value !== null && !(value > 0 && value <= 60)) {
      issues.push(`interest rate ${name} ${value}% is outside (0, 60]: dropped`);
      if (name === 'min') min = null;
      else max = null;
    }
  }
  if (min !== null && max !== null && min > max) {
    issues.push(`interest rate min ${min} > max ${max}: swapped`);
    [min, max] = [max, min];
  }
  return { interest_rate_min: min, interest_rate_max: max };
}

function ages(raw, issues) {
  let min = num(raw.min_age);
  let max = num(raw.max_age);
  if (min !== null && !(min >= 18 && min <= 100)) { issues.push(`min age ${min} out of range: dropped`); min = null; }
  if (max !== null && !(max >= 18 && max <= 100)) { issues.push(`max age ${max} out of range: dropped`); max = null; }
  if (min !== null && max !== null && min > max) {
    issues.push(`min age ${min} > max age ${max}: both dropped`);
    return { min_age: null, max_age: null };
  }
  return { min_age: min, max_age: max };
}

const SCORE_MENTION = /\b(?:credit|cibil)\s+score\b/i;
const SCORE_REQUIRED = /\b(?:minimum|at least|need|needs|required|requires|must|eligible)\b|\bor (?:higher|more|above)\b|\band above\b/i;
const SCORE_PREFERRED = /\b(?:good|ideal|prefer|preferred|generally|recommended|better|improves?|likely|chances|typically|consider|considered)\b/i;

/** The lowest credit score a page states as a requirement, or null: the text, read by code. */
function statedMinimumScore(pageText) {
  let lowest = null;
  for (const sentence of String(pageText || '').split(/(?<=[.?!])\s+|\n+|\s\|\s/)) {
    if (!SCORE_MENTION.test(sentence) || !SCORE_REQUIRED.test(sentence) || SCORE_PREFERRED.test(sentence)) continue;
    for (const match of sentence.matchAll(/\b([3-9]\d{2})\b/g)) {
      const value = Number(match[1]);
      if (value >= 300 && value <= 900 && (lowest === null || value < lowest)) lowest = value;
    }
  }
  return lowest;
}

function creditScore(raw, issues, soft, pageMinimum) {
  const score = num(raw.min_credit_score);
  let minimum = null;
  if (score !== null && raw.credit_score_kind !== 'not_stated') {
    if (!(score >= 300 && score <= 900)) {
      issues.push(`credit score ${score} out of 300-900: dropped`);
    } else if (raw.credit_score_kind === 'preferred') {
      soft.push({
        text: `Credit score ${score}+ preferred`,
        class: 'compilable',
        depends_on: ['credit_score'],
        origin: 'preferred_score',
        rule: { field: 'credit_score', op: '>=', value: score, effect: 'rank' },
      });
    } else {
      minimum = Math.round(score);
    }
  }
  if (pageMinimum !== null && (minimum === null || pageMinimum < minimum)) {
    issues.push(`the page states a minimum credit score of ${pageMinimum}: used as the filter`);
    return { min_credit_score: pageMinimum, score_from_page: true };
  }
  return { min_credit_score: minimum };
}

const CONCESSION = /\b(?:employees?|staff|salary account|account holders?|corp(?:orate)? salary|existing customers?|pre-?approved)\b/i;
const isConcession = (condition) => Boolean(condition) && CONCESSION.test(condition) && !/\bnon[- ]/i.test(condition);

function income(raw, issues, soft, confidence) {
  const thresholds = [];
  for (const t of Array.isArray(raw.income_thresholds) ? raw.income_thresholds : []) {
    const amount = num(t.amount);
    if (amount === null || amount <= 0) continue;
    const monthly = t.period === 'annual' ? Math.round(amount / 12) : amount;
    if (monthly > MAX_MONTHLY_INCOME) {
      issues.push(`income ${rupees(monthly)}/month is implausible: dropped`);
      continue;
    }
    if (t.period !== 'annual' && monthly >= SUSPICIOUS_MONTHLY) {
      issues.push(`monthly income ${rupees(monthly)} looks annual: confidence lowered`);
      confidence.min_monthly_income = Math.min(confidence.min_monthly_income, 0.4);
    }
    const employment = [...new Set((t.employment || []).filter((e) => EMPLOYMENT.includes(e)))];
    thresholds.push({ monthly, employment, condition: text(t.condition) || null });
  }
  if (!thresholds.length) return { min_monthly_income: null };

  const general = thresholds.filter((t) => !isConcession(t.condition));
  const floor = Math.min(...(general.length ? general : thresholds).map((t) => t.monthly));
  for (const t of thresholds) {
    if (t.condition) {
      soft.push({
        text: `Minimum income ${rupees(t.monthly)}/month ${t.condition}`.replace(/\s+/g, ' '),
        class: 'unknown_field',
        depends_on: [],
        origin: 'income_tier',
      });
    } else if (t.monthly > floor && t.employment.length && t.employment.length < EMPLOYMENT.length) {
      soft.push({
        text: `Minimum income ${rupees(t.monthly)}/month for ${t.employment.join(' / ')}`,
        class: 'compilable',
        depends_on: ['monthly_income', 'employment_status'],
        origin: 'income_tier',
        rule: { field: 'monthly_income', op: '>=', value: t.monthly, when: { employment_status: t.employment } },
      });
    } else if (t.monthly > floor) {
      issues.push(`conflicting unconditional income thresholds; using the lowest, ${rupees(floor)}`);
      confidence.min_monthly_income = Math.min(confidence.min_monthly_income, 0.5);
    }
  }
  return { min_monthly_income: floor };
}

function employmentAllowed(raw) {
  const allowed = [...new Set((raw.employment_allowed || []).filter((e) => EMPLOYMENT.includes(e)))];
  if (!allowed.length || allowed.length === EMPLOYMENT.length) return { allowed_employment: null };
  return { allowed_employment: EMPLOYMENT.filter((e) => allowed.includes(e)) };
}

function otherCriteria(raw, issues, soft) {
  for (const c of Array.isArray(raw.other_criteria) ? raw.other_criteria : []) {
    const body = text(c.text);
    if (!body) continue;
    let cls = CLASSES.includes(c.class) ? c.class : 'unknown_field';
    let dependsOn = [...new Set((c.depends_on || []).filter((f) => FACTS.includes(f)))];
    if (cls === 'unknown_field') dependsOn = [];
    if (cls !== 'unknown_field' && !dependsOn.length) {
      issues.push(`"${body}" is ${cls} but depends on none of our fields: treated as unknown_field`);
      cls = 'unknown_field';
    }
    soft.push({ text: body, class: cls, depends_on: dependsOn, origin: 'page' });
  }
}

// S6: a hard filter the extraction is unsure about is not used as a filter.
const GUARDED = [
  { field: 'min_monthly_income', fact: 'monthly_income', label: 'Minimum monthly income', show: rupees },
  { field: 'min_credit_score', fact: 'credit_score', label: 'Minimum credit score', show: String },
  { field: 'allowed_employment', fact: 'employment_status', label: 'Eligible employment', show: (v) => v.join(', ') },
];

function confidenceGuard(columns, confidence, threshold, issues, soft) {
  for (const { field, fact, label, show } of GUARDED) {
    if (columns[field] !== null && confidence[field] < threshold) {
      soft.push({
        text: `${label} stated as ${show(columns[field])} (extraction confidence ${confidence[field]})`,
        class: 'fuzzy',
        depends_on: [fact],
        origin: 'low_confidence',
      });
      issues.push(`${field} confidence ${confidence[field]} < ${threshold}: not used as a filter`);
      columns[field] = null;
    }
  }
  const ageConfident = confidence.age >= threshold;
  if (!ageConfident && (columns.min_age !== null || columns.max_age !== null)) {
    soft.push({
      text: `Age ${columns.min_age ?? '?'}-${columns.max_age ?? '?'} years (extraction confidence ${confidence.age})`,
      class: 'fuzzy',
      depends_on: ['age'],
      origin: 'low_confidence',
    });
    issues.push(`age confidence ${confidence.age} < ${threshold}: not used as a filter`);
    columns.min_age = null;
    columns.max_age = null;
  }
}

function normalizeProduct(raw, sourceUrl, threshold, pageMinimum = null, generalMinimum = null) {
  const issues = [];
  const lender = text(raw.lender);
  const productName = text(raw.product_name);
  if (!lender || !productName) return { product: null, issues: ['product without lender or name: dropped'] };

  const c = raw.confidence || {};
  const clamp = (v) => Math.round(Math.min(1, Math.max(0, num(v) ?? 0)) * 100) / 100;
  const confidence = {
    interest_rate: clamp(c.interest_rate),
    age: clamp(c.age),
    min_credit_score: clamp(c.credit_score),
    min_monthly_income: clamp(c.income),
    allowed_employment: clamp(c.employment),
  };

  const soft = [];
  const { score_from_page: scoreFromPage, ...score } = creditScore(raw, issues, soft, pageMinimum);
  if (scoreFromPage) confidence.min_credit_score = 1; // read from the page text by code
  const columns = {
    ...rates(raw, issues),
    ...ages(raw, issues),
    ...score,
    ...income(raw, issues, soft, confidence),
    ...employmentAllowed(raw),
  };
  otherCriteria(raw, issues, soft);
  const ownCriteria = ['min_age', 'max_age', 'min_monthly_income'].some((f) => columns[f] !== null)
    || (columns.allowed_employment ?? []).length > 0
    || soft.some((c) => c.class === 'fuzzy' || c.class === 'compilable');
  if (columns.min_credit_score === null && generalMinimum !== null && ownCriteria) {
    columns.min_credit_score = generalMinimum;
    confidence.min_credit_score = 1; // read from the page text by code
    issues.push(`no score of its own: the source's general requirement, ${generalMinimum}, applies`);
  }
  confidenceGuard(columns, confidence, threshold, issues, soft);

  const seen = new Set();
  const softCriteria = soft
    .filter((s) => (seen.has(s.text.toLowerCase()) ? false : seen.add(s.text.toLowerCase())))
    .sort((a, b) => a.class.localeCompare(b.class) || a.text.localeCompare(b.text));
  const criteria = { ...columns, soft_criteria: softCriteria };

  return {
    product: {
      lender,
      product_name: productName,
      source_url: sourceUrl,
      ...columns,
      soft_criteria: softCriteria,
      field_confidence: confidence,
      criteria_json: canonical(criteria),
      criteria_hash: sha256(criteria),
    },
    issues: issues.map((i) => `${productName}: ${i}`),
  };
}

const hardFieldCount = (p) =>
  ['min_age', 'max_age', 'min_credit_score', 'min_monthly_income', 'allowed_employment', 'interest_rate_min']
    .filter((f) => p[f] !== null).length;

// One lender can appear under its full name and its acronym on the same page ("IIFL" and
// "India Infoline Finance Ltd."), or a product under the lender's initials ("PNB Personal
// Loan"). Two entries are the same product when their lenders match by name or acronym (a
// single-word name equal to the other's initials) and their product names match once lender
// words, initials and generic words are removed.
const words = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
const GENERIC = new Set(['bank', 'ltd', 'limited', 'finance', 'financial', 'services', 'powered', 'by']);

function lenderForms(lender) {
  const w = words(lender);
  return {
    core: w.filter((x) => !['bank', 'ltd', 'limited'].includes(x)).join(' '),
    initials: w.map((x) => x[0]).join(''),
    single: w.length === 1 ? w[0] : null,
  };
}

function sameLender(a, b) {
  const x = lenderForms(a);
  const y = lenderForms(b);
  return x.core === y.core || (x.single !== null && x.single === y.initials)
    || (y.single !== null && y.single === x.initials);
}

// The product name without either lender's words or initials, so "PNB Personal Loan" and
// "Punjab National Bank Personal Loan" compare equal.
function productCore(p, otherLender) {
  const drop = new Set([...words(p.lender), ...words(otherLender), lenderForms(p.lender).initials,
                        lenderForms(otherLender).initials, ...GENERIC]);
  return words(p.product_name).filter((x) => !drop.has(x)).join(' ');
}

function validate(extraction, sourceUrl, threshold, pageMinimum = null, generalMinimum = null) {
  const kept = [];
  const issues = [];
  let dropped = 0;
  for (const raw of Array.isArray(extraction?.products) ? extraction.products : []) {
    const { product, issues: productIssues } = normalizeProduct(raw, sourceUrl, threshold, pageMinimum, generalMinimum);
    issues.push(...productIssues);
    if (!product) { dropped += 1; continue; }
    const at = kept.findIndex((k) => sameLender(k.lender, product.lender)
      && productCore(k, product.lender) === productCore(product, k.lender));
    if (at === -1) { kept.push(product); continue; }
    issues.push(`${product.product_name}: same product as ${kept[at].product_name}, kept the more complete entry`);
    dropped += 1;
    if (hardFieldCount(product) > hardFieldCount(kept[at])) kept[at] = product;
  }
  return { products: kept, issues, dropped };
}

// ---- n8n entry point ----
const gateway = $input.first().json;
const source = $('Loop over sources').first().json;
const page = $('Hash page text').first().json;
const config = $('Load app_config').first().json.config;
const threshold = Number(config.extraction_confidence_min);
const stated = statedMinimumScore(page.text);
const pageMinimum = source.kind === 'lender' ? stated : null; // the lender's own minimum
const generalMinimum = source.kind === 'aggregator' ? stated : null; // the source's general one
const { products, issues, dropped } = validate(gateway.data, source.page_urls[0], threshold, pageMinimum, generalMinimum);
return [{
  json: {
    products,
    products_found: products.length,
    products_dropped: dropped,
    issues,
    content_hash: page.content_hash,
    llm_calls: gateway.calls,
    tokens_in: gateway.tokens_in,
    tokens_out: gateway.tokens_out,
  },
}];
